import logging
import socket
import time

from taf.hw.optical_switch.exceptions import TooManyRetries


class TCPClient:

    def __init__(self, host, port, timeout, buffer_size, encoding, interval):
        self.host = host
        self.port = port
        self.timeout = timeout
        self.buffer_size = buffer_size
        self.encoding = encoding
        self.interval = interval
        self.tcp_conn = self._connect(self.host, self.port, self.timeout)
        self._logger = logging.getLogger(__name__)
        self._logger.setLevel(logging.DEBUG)

    @staticmethod
    def _connect(host, port, timeout):
        conn = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        conn.settimeout(timeout)
        conn.connect((host, port))
        return conn

    def disconnect(self):
        self.tcp_conn.shutdown(socket.SHUT_WR)
        self.tcp_conn.close()

    def execute(self, msg, read, stop_msg=None):
        msg = self._get_encoded_msg(msg)
        self._logger.debug(f"Sending TCP message: {msg}")
        self.tcp_conn.send(msg)
        if read:
            response = self.tcp_conn.recv(self.buffer_size)
            if stop_msg:
                while not response.endswith(stop_msg):
                    response += self.tcp_conn.recv(self.buffer_size)
            self._logger.debug(f"TCP response: {response}")
            return self._decode_response(response)

    def execute_with_retry(self, msg, retry, read, stop_msg=None):
        curr_tries = 0
        self._logger.debug(f"Sending TCP message: {msg} with retry")
        while retry > curr_tries:
            try:
                curr_tries = curr_tries + 1
                response = self.execute(msg, read, stop_msg)
                return response
            except socket.timeout:
                self._logger.warning(
                    f"Socket connection timed out during {curr_tries} attempt for msg {msg}"
                )
            except Exception as e:
                self._logger.warning(
                    f"failed to execute {msg} during {curr_tries} attempt. Error: {e}"
                )
            time.sleep(self.interval)

        raise TooManyRetries(f"Failed to execute {msg} in {retry} attempts")

    def _decode_response(self, response):
        if isinstance(response, bytes):
            return response.decode(self.encoding)
        else:
            return response

    @staticmethod
    def _get_encoded_msg(msg):
        if isinstance(msg, str):
            return msg.encode()
        else:
            return msg
